/**
 * web-detect-bench.ts
 *
 * Per-site latency benchmark. NPM + CDN cache is assumed to already be built
 * (LoC≥6 inline-aware, generated by populate-fingerprint-cache.ts). For each
 * site, we measure:
 *
 *   tHash   — wall time spent extracting POG hashes from raw JS in
 *             `src/data/data-never-remove/{site}/`
 *   tDetect — wall time spent doing the inverted-index match + per-(lib,ver)
 *             scoring (same matchThreshold logic as web-detect-eval.ts)
 *   total   — tHash + tDetect (per-site end-to-end at deploy time)
 *
 * Index loading is one-off and reported separately.
 *
 * Env:
 *   FP_CACHE_DIR        cache to use (default `data/fingerprint-cache`)
 *   MATCH_THRESHOLD     default 85 (percent)
 *   MIN_POG_NODES       default 0 (LoC≥6 cache build already drops short fns)
 *   MIN_CANDIDATE       default 5
 *   BENCH_FORCE_GC       set to 1 to run gc() between phases (requires --expose-gc)
 *   SITE_SRC_DIR        crawled-script root (default src/data/data-never-remove)
 *   SITE_FILTER         comma-separated site names (default: all sites
 *                       under data-never-remove with non-zero JS files)
 *   BENCH_OUTPUT        path to CSV (default data/bench-per-site.csv)
 */

import * as fs from 'fs';
import * as path from 'path';
import { performance } from 'perf_hooks';
import { Worker } from 'worker_threads';

import { loadWebBlacklist } from '../fingerprint-collector/web-blacklist';
import { filterAndFindEntries } from '../fingerprint-collector/module-filter';
import fingerprintCollector, { FingerprintTimings } from '../fingerprint-collector';
import { DepGraph, FileHashRecord } from '../types/depgraph';

const rootDir = process.cwd();
const siteSrcEnv = process.env['SITE_SRC_DIR'] ?? 'src/data/data-never-remove';
const siteSrcDir = siteSrcEnv.startsWith('/') ? siteSrcEnv : path.join(rootDir, siteSrcEnv);

const cacheDirEnv = process.env['FP_CACHE_DIR'] ?? 'src/data/fingerprint-cache';
const cacheDir = cacheDirEnv.startsWith('/') ? cacheDirEnv : path.join(rootDir, cacheDirEnv);

const thresholdPercent = parseFloat(process.env['MATCH_THRESHOLD'] ?? '85');
if (!Number.isFinite(thresholdPercent) || thresholdPercent < 0 || thresholdPercent > 100) {
  console.error(`[Fatal] MATCH_THRESHOLD must be 0-100`);
  process.exit(1);
}
const matchThreshold = thresholdPercent / 100;

const MIN_POG_NODES = parseInt(process.env['MIN_POG_NODES'] ?? '0', 10);
const minCandidate = parseInt(process.env['MIN_CANDIDATE'] ?? '5', 10);
const shouldForceGc = process.env['BENCH_FORCE_GC'] === '1';

const benchOut = process.env['BENCH_OUTPUT'] ?? 'data/bench-per-site.csv';
type GlobalWithGc = typeof globalThis & { gc?: () => void };
const exposedGlobal = global as GlobalWithGc;

function getWorkerExecArgv(): string[] {
  const args = [...process.execArgv].filter(
    (a) => a !== '--expose-gc' && !a.startsWith('--expose-gc=') && a !== '--expose_wasm'
  );
  const hasTsNodeRegister = args.some((a, i) => {
    if (a === '-r' || a === '--require') {
      return args[i + 1]?.includes('ts-node/register/transpile-only') ?? false;
    }
    return a.startsWith('-r=') || a.startsWith('--require=')
      ? a.includes('ts-node/register/transpile-only')
      : false;
  });
  if (!hasTsNodeRegister) {
    args.push('--require', 'ts-node/register/transpile-only');
  }
  return args;
}

async function forceGc(): Promise<void> {
  if (!shouldForceGc || !exposedGlobal.gc) return;
  exposedGlobal.gc();
  await new Promise((resolve) => setImmediate(resolve));
  exposedGlobal.gc();
}

// ── walk JS files ──────────────────────────────────────────────────────────

function collectJsFilesRecursive(dir: string): string[] {
  const out: string[] = [];
  if (!fs.existsSync(dir)) return out;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) out.push(...collectJsFilesRecursive(full));
    else if (entry.isFile()) out.push(full);
  }
  return out;
}

// Per-site extraction in a fresh Worker. Bench's repeated SC analysis across
// 68+ sites in one node process accumulates V8 IC / heap state and pinterest
// (etc.) gets ~10× slower than its true cost. Spawning a Worker per site
// resets the isolate so each site's reported timings reflect its real work.
function runExtractInWorker(site: string): Promise<{
  hashes: Set<string>;
  fileCount: number;
  failCount: number;
  timings: Required<FingerprintTimings>;
}> {
  const workerPath = path.join(__dirname, 'web-detect-bench-extract-worker.ts');
  const workerExecArgv = getWorkerExecArgv();
  return new Promise((resolve, reject) => {
    const worker = new Worker(workerPath, {
      workerData: { site, siteSrcDir },
      execArgv: workerExecArgv,
    });
    let settled = false;
    worker.once('message', (msg: any) => {
      settled = true;
      void worker
        .terminate()
        .catch(() => {})
        .finally(() => {
          resolve({
            hashes: new Set<string>(msg.hashes),
            fileCount: msg.fileCount,
            failCount: msg.failCount,
            timings: msg.timings as Required<FingerprintTimings>,
          });
        });
    });
    worker.once('error', (err) => { if (!settled) { settled = true; reject(err); } });
    worker.once('exit', (code) => {
      if (!settled) reject(new Error(`extract worker exited code=${code} for ${site}`));
    });
  });
}

function extractSiteHashes(site: string): {
  hashes: Set<string>;
  fileCount: number;
  failCount: number;
  timings: Required<FingerprintTimings>;
} {
  const dir = path.join(siteSrcDir, site);
  const files = collectJsFilesRecursive(dir);
  const hashes = new Set<string>();
  let failCount = 0;
  const timings: FingerprintTimings = { parseMs: 0, scMs: 0, collectorMs: 0, pogMs: 0, hashMs: 0 };
  for (const f of files) {
    let raw: string;
    try { raw = fs.readFileSync(f, 'utf-8'); } catch { failCount++; continue; }
    try {
      // Note: site hashing intentionally has NO LoC filter (matches gen-web-hashes.ts)
      for (const h of fingerprintCollector(raw, undefined, { timings })) {
        if (h.hash) hashes.add(h.hash);
      }
    } catch {
      failCount++;
    }
  }
  return {
    hashes, fileCount: files.length, failCount,
    timings: timings as Required<FingerprintTimings>,
  };
}

// ── load cache & build indexes (one-off, mirrors web-detect-eval.ts) ──────

interface AllLibsEntry { id: number; versions: string[]; hashCnt: number[]; relPath?: string }
type AllLibsT = Record<string, AllLibsEntry>;
type AllHashT = Record<string, Record<string, Record<string, Array<[number, number]>>>>;
type AllDepsT = Record<string, { nodes: number[]; edges: [number, number][]; unresolved: [number, string][] }>;

console.log(`[bench] cacheDir=${cacheDir}`);
console.log(`[bench] threshold=${thresholdPercent}% MIN_POG_NODES=${MIN_POG_NODES} minCandidate=${minCandidate}`);

const tLoadStart = Date.now();
const webBL = loadWebBlacklist(rootDir, 0.6);
console.log(`[web-blacklist] ${webBL.size} hashes`);

// Everything except alldeps is only read while the derived maps below are built, but a
// module-level `const` keeps the parsed object alive for the whole run — worth ~0.7 GB of
// resident memory that no gc() can reclaim, because the reference is live, not garbage.
// Declared `let` so each can be released at its `[release]` point once it is dead.
let npmLibsData: AllLibsT | null =
  JSON.parse(fs.readFileSync(path.join(cacheDir, 'alllibs.json'), 'utf-8')) as AllLibsT;
let npmHashData: AllHashT | null =
  JSON.parse(fs.readFileSync(path.join(cacheDir, 'allhash.json'), 'utf-8')) as AllHashT;
let npmDepsData: AllDepsT | null =
  JSON.parse(fs.readFileSync(path.join(cacheDir, 'alldeps.json'), 'utf-8')) as AllDepsT;
let cdnLibsData: AllLibsT | null =
  JSON.parse(fs.readFileSync(path.join(cacheDir, 'cdn-alllibs.json'), 'utf-8')) as AllLibsT;
let cdnHashData: AllHashT | null =
  JSON.parse(fs.readFileSync(path.join(cacheDir, 'cdn-allhash.json'), 'utf-8')) as AllHashT;

const tIdxStart = Date.now();

interface FileLibMeta { baseLib: string; relPath: string; versions: string[]; hashCnt: number[] }
const fileLibById = new Map<number, FileLibMeta>();
const fileLibIdsByBaseLib = new Map<string, number[]>();
for (const [key, entry] of Object.entries(npmLibsData!)) {
  const baseLib = key.split('____')[0];
  const relPath = entry.relPath ?? key.slice(baseLib.length + 4).replace(/\./g, '/') + '.js';
  fileLibById.set(entry.id, { baseLib, relPath, versions: entry.versions, hashCnt: entry.hashCnt });
  let arr = fileLibIdsByBaseLib.get(baseLib);
  if (!arr) { arr = []; fileLibIdsByBaseLib.set(baseLib, arr); }
  arr.push(entry.id);
}

// The cache stores each hash's version span as a range, and expanding every range into a
// per-version Set is what made this index enormous: 1.05 M (libId,ver) Sets holding 22.6 M
// members, ~1 GB, for data that is only read while the fingerprints are precomputed.
//
// Keep the ranges instead (~78 MB for the same information) and expand one library at a
// time, on demand. Total expansion work is unchanged; only the peak is bounded, because a
// library's Sets are dropped as soon as the next library needs the room.
interface HashRange { hash: string; lo: number; hi: number; webBL: boolean }
const hashRangesByLib = new Map<number, HashRange[]>();
for (const [nodesStr, bucket] of Object.entries(npmHashData!)) {
  if (Number(nodesStr) < MIN_POG_NODES) continue;
  for (const [hash, libMap] of Object.entries(bucket)) {
    const isWebBL = webBL.has(hash);
    for (const [libIdStr, ranges] of Object.entries(libMap)) {
      const libId = Number(libIdStr);
      if (!fileLibById.has(libId)) continue;
      let arr = hashRangesByLib.get(libId);
      if (!arr) { arr = []; hashRangesByLib.set(libId, arr); }
      for (const [lo, hi] of ranges) arr.push({ hash, lo, hi, webBL: isWebBL });
    }
  }
}
npmHashData = null;  // [release] fully consumed into hashRangesByLib
npmLibsData = null;  // [release] fully consumed into fileLibById (which holds its subarrays)

/**
 * Per-version hash Sets for one library, materialized on demand.
 *
 * Both consumers (the composite pass and the fingerprint precompute) walk libraries in
 * order, so a tiny cache of recently expanded libraries turns every lookup into a hit
 * without ever holding more than a handful of libraries' Sets at once.
 */
// Scope, not size, is what keeps this cheap. Both consumers finish with one library (the
// composite pass) or one baseLib (the precompute) before moving on, so the caller clears
// the cache at that boundary and every lookup in between is a hit. A fixed-size LRU is the
// wrong shape here: a baseLib with more files than the cache holds re-expands all of them
// on every one of its versions, which cost 106 s of precompute when tried at 64 entries.
const expandedCache = new Map<number, { raw: Map<number, Set<string>>; filtered: Map<number, Set<string>> }>();
function expandLib(libId: number) {
  const hit = expandedCache.get(libId);
  if (hit) return hit;
  const raw = new Map<number, Set<string>>();
  const filtered = new Map<number, Set<string>>();
  for (const r of hashRangesByLib.get(libId) ?? []) {
    for (let vi = r.lo; vi <= r.hi; vi++) {
      let rs = raw.get(vi);
      if (!rs) { rs = new Set(); raw.set(vi, rs); }
      rs.add(r.hash);
      if (r.webBL) continue;
      let fs2 = filtered.get(vi);
      if (!fs2) { fs2 = new Set(); filtered.set(vi, fs2); }
      fs2.add(r.hash);
    }
  }
  const entry = { raw, filtered };
  expandedCache.set(libId, entry);
  return entry;
}

// ── file-level embedded-copy detection (composite hash + birth) ──
const { createHash } = require('crypto') as typeof import('crypto');
const birthPath = path.join(rootDir, 'src/data/birth_sanitized.json');
let birthInfo: Record<string, Record<string, string>> = {};
try { birthInfo = JSON.parse(fs.readFileSync(birthPath, 'utf-8')); } catch {}

interface FileLibEntry { libId: number; verIdx: number; baseLib: string; version: string }
const compositeToEntries = new Map<string, FileLibEntry[]>();
// Walks libraries so each one's per-version Sets are expanded, consumed and dropped,
// instead of materializing all 1.05 M of them up front.
for (const libId of hashRangesByLib.keys()) {
  const meta = fileLibById.get(libId);
  if (!meta) continue;
  expandedCache.clear();  // one library at a time; nothing here is reused across libraries
  for (const [verIdx, rawSet] of expandLib(libId).raw) {
    if (rawSet.size < 1) continue;
    const sorted = [...rawSet].sort();
    const composite = createHash('sha1').update(sorted.join('|')).digest('hex');
    const version = meta.versions[verIdx];
    if (!version) continue;
    let arr = compositeToEntries.get(composite);
    if (!arr) { arr = []; compositeToEntries.set(composite, arr); }
    arr.push({ libId, verIdx, baseLib: meta.baseLib, version });
  }
}
expandedCache.clear();  // the raw Sets are only needed for the composites above

const embeddedFileLibVer = new Set<string>();
for (const [_c, entries] of compositeToEntries) {
  if (entries.length < 2) continue;
  const baseLibs = new Set(entries.map((e) => e.baseLib));
  if (baseLibs.size < 2) continue;
  const oldestByBaseLib = new Map<string, number>();
  for (const e of entries) {
    const raw = birthInfo[e.baseLib]?.[e.version];
    if (!raw) continue;
    const t = new Date(raw).getTime();
    const cur = oldestByBaseLib.get(e.baseLib);
    if (cur === undefined || t < cur) oldestByBaseLib.set(e.baseLib, t);
  }
  if (oldestByBaseLib.size === 0) continue;
  let winner = ''; let winnerTime = Number.POSITIVE_INFINITY;
  for (const [bl, t] of oldestByBaseLib) { if (t < winnerTime) { winnerTime = t; winner = bl; } }
  for (const e of entries) if (e.baseLib !== winner) embeddedFileLibVer.add(`${e.libId}@${e.verIdx}`);
}
compositeToEntries.clear();  // [release] only embeddedFileLibVer is needed downstream

// ── cdn indexes ──
interface CdnFileLibMeta { baseLib: string; relPath: string; versions: string[] }
const cdnFileLibById = new Map<number, CdnFileLibMeta>();
for (const [key, entry] of Object.entries(cdnLibsData!)) {
  const baseLib = key.split('____')[0];
  const relPath = entry.relPath ?? key.slice(baseLib.length + 4).replace(/\./g, '/') + '.js';
  cdnFileLibById.set(entry.id, { baseLib, relPath, versions: entry.versions });
}

const cdnHashByLibVer = new Map<string, Set<string>>();
const cdnVariantHashesByLibVer = new Map<string, Map<string, Set<string>>>();
for (const [nodesStr, bucket] of Object.entries(cdnHashData!)) {
  if (Number(nodesStr) < MIN_POG_NODES) continue;
  for (const [hash, libMap] of Object.entries(bucket)) {
    for (const [libIdStr, ranges] of Object.entries(libMap)) {
      const info = cdnFileLibById.get(Number(libIdStr));
      if (!info) continue;
      for (const [lo, hi] of ranges) {
        for (let vi = lo; vi <= hi; vi++) {
          const version = info.versions[vi];
          if (!version) continue;
          const verKey = `${info.baseLib}@${version}`;
          let vset = cdnHashByLibVer.get(verKey);
          if (!vset) { vset = new Set(); cdnHashByLibVer.set(verKey, vset); }
          vset.add(hash);
          let variantMap = cdnVariantHashesByLibVer.get(verKey);
          if (!variantMap) { variantMap = new Map(); cdnVariantHashesByLibVer.set(verKey, variantMap); }
          let vhs = variantMap.get(info.relPath);
          if (!vhs) { vhs = new Set(); variantMap.set(info.relPath, vhs); }
          vhs.add(hash);
        }
      }
    }
  }
}
cdnHashData = null;  // [release] fully consumed into cdnHashByLibVer / cdnVariantHashesByLibVer
cdnLibsData = null;  // [release] fully consumed into cdnFileLibById

const cdnVersionsByLib = new Map<string, string[]>();
for (const libVerKey of cdnHashByLibVer.keys()) {
  const at = libVerKey.lastIndexOf('@');
  const baseLib = libVerKey.slice(0, at);
  const version = libVerKey.slice(at + 1);
  let arr = cdnVersionsByLib.get(baseLib);
  if (!arr) { arr = []; cdnVersionsByLib.set(baseLib, arr); }
  arr.push(version);
}
for (const [bl, vers] of cdnVersionsByLib) cdnVersionsByLib.set(bl, [...vers].sort().reverse());

const cdnHashToLibVers = new Map<string, Array<{ baseLib: string; version: string }>>();
for (const [libVerKey, hashSet] of cdnHashByLibVer) {
  const at = libVerKey.lastIndexOf('@');
  const baseLib = libVerKey.slice(0, at);
  const version = libVerKey.slice(at + 1);
  for (const h of hashSet) {
    if (webBL.has(h)) continue;
    let arr = cdnHashToLibVers.get(h);
    if (!arr) { arr = []; cdnHashToLibVers.set(h, arr); }
    arr.push({ baseLib, version });
  }
}

const tIdxEnd = Date.now();
console.log(
  `[index] one-off load+build = ${((tIdxEnd - tLoadStart) / 1000).toFixed(1)}s (cache read ${((tIdxStart - tLoadStart) / 1000).toFixed(1)}s, index build ${((tIdxEnd - tIdxStart) / 1000).toFixed(1)}s)`
);
console.log(
  `[index] npm: ${hashRangesByLib.size} libs (hash ranges, expanded per library on demand)` +
  ` · cdn: ${cdnHashByLibVer.size} (lib,ver) · cdnHashToLibVers ${cdnHashToLibVers.size}`
);

// ── per-(lib,ver) fingerprint assembly (matches web-detect-eval.ts) ──

function assembleFingerprint(baseLib: string, version: string, cdnBundleHashes: Set<string>)
  : { fileHashes: Record<string, FileHashRecord>; depgraph: DepGraph; mode: 'npm-decomposed' | 'cdn-bundle' | 'empty' } {
  const libIds = fileLibIdsByBaseLib.get(baseLib) ?? [];
  const npmFileHashes: Record<string, FileHashRecord> = {};
  let npmHasThisVer = false;
  for (const libId of libIds) {
    const meta = fileLibById.get(libId)!;
    const vi = meta.versions.indexOf(version);
    if (vi < 0) continue;
    npmHasThisVer = true;
    const key = `${libId}@${vi}`;
    if (embeddedFileLibVer.has(key)) continue;
    const hashSet = expandLib(libId).filtered.get(vi);
    if (!hashSet || hashSet.size === 0) continue;
    let matchedInCdn = 0;
    for (const h of hashSet) if (cdnBundleHashes.has(h)) matchedInCdn++;
    const cdnRatio = hashSet.size === 0 ? 1 : matchedInCdn / hashSet.size;
    if (cdnRatio < matchThreshold) continue;
    const intersected = [...hashSet].filter((h) => cdnBundleHashes.has(h));
    if (intersected.length === 0) continue;
    npmFileHashes[meta.relPath] = { hashes: intersected, funcCount: meta.hashCnt[vi] ?? 0 };
  }
  if (npmHasThisVer && Object.keys(npmFileHashes).length > 0) {
    const present = new Set(Object.keys(npmFileHashes));
    const depRaw = npmDepsData![`${baseLib}@${version}`];
    let depgraph: DepGraph;
    if (depRaw) {
      const idToRel = (id: number): string => fileLibById.get(id)?.relPath ?? String(id);
      const fullNodes = depRaw.nodes.map(idToRel);
      const fullEdges = depRaw.edges.map(([a, b]) => [idToRel(a), idToRel(b)] as [string, string]);
      const adj = new Map<string, string[]>();
      for (const n of fullNodes) adj.set(n, []);
      for (const [a, b] of fullEdges) {
        let arr = adj.get(a); if (!arr) { arr = []; adj.set(a, arr); } arr.push(b);
      }
      const newEdges: [string, string][] = [];
      const seen = new Set<string>();
      for (const src of fullNodes) {
        if (!present.has(src)) continue;
        const visited = new Set<string>();
        const stack: string[] = [...(adj.get(src) ?? [])];
        while (stack.length) {
          const cur = stack.pop()!;
          if (visited.has(cur)) continue;
          visited.add(cur);
          if (present.has(cur)) {
            if (cur === src) continue;
            const k = `${src}\t${cur}`;
            if (!seen.has(k)) { seen.add(k); newEdges.push([src, cur]); }
          } else {
            for (const nxt of (adj.get(cur) ?? [])) stack.push(nxt);
          }
        }
      }
      depgraph = {
        nodes: fullNodes.filter((n) => present.has(n)).sort(),
        edges: newEdges,
        unresolved: depRaw.unresolved.map(([a, spec]) => [idToRel(a), spec] as [string, string]).filter(([a]) => present.has(a)),
      };
    } else {
      depgraph = { nodes: [...present].sort(), edges: [], unresolved: [] };
    }
    return { fileHashes: npmFileHashes, depgraph, mode: 'npm-decomposed' };
  }
  if (process.env['ENABLE_CDN_BUNDLE_FALLBACK'] !== '1') {
    return { fileHashes: {}, depgraph: { nodes: [], edges: [], unresolved: [] }, mode: 'empty' };
  }
  const variantMap = cdnVariantHashesByLibVer.get(`${baseLib}@${version}`);
  if (!variantMap || variantMap.size === 0) {
    return { fileHashes: {}, depgraph: { nodes: [], edges: [], unresolved: [] }, mode: 'empty' };
  }
  const cdnFileHashes: Record<string, FileHashRecord> = {};
  const nodes: string[] = [];
  for (const [relPath, hs] of variantMap) {
    const cleaned = [...hs].filter((h) => !webBL.has(h));
    if (cleaned.length === 0) continue;
    cdnFileHashes[relPath] = { hashes: cleaned, funcCount: cleaned.length };
    nodes.push(relPath);
  }
  if (nodes.length === 0) return { fileHashes: {}, depgraph: { nodes: [], edges: [], unresolved: [] }, mode: 'empty' };
  return { fileHashes: cdnFileHashes, depgraph: { nodes: nodes.sort(), edges: [], unresolved: [] }, mode: 'cdn-bundle' };
}

// ── pre-compute assembleFingerprint per (baseLib, version) ──
// All inputs to assembleFingerprint are site-independent (cdnBundleHashes,
// hashRangesByLib, embeddedFileLibVer, npmDepsData are all built once at
// startup), so the output is the same for every site that scores this pair.
// Precomputing once trims the per-site detect loop's `assemble` cost from
// ~1500 ms to a Map.get(), and makes those inputs dead afterwards — they are
// released below rather than left resident for the whole run.
type AssembleResult = ReturnType<typeof assembleFingerprint>;
const assembledByLibVer = new Map<string, AssembleResult>();
{
  const tAsm = performance.now();
  for (const [baseLib, versions] of cdnVersionsByLib) {
    // Every version of this baseLib reads the same libIds, so expand them once here and
    // drop them before the next baseLib — the cache is scoped to the loop, not size-capped.
    expandedCache.clear();
    for (const version of versions) {
      const cdnBundle = cdnHashByLibVer.get(`${baseLib}@${version}`);
      if (!cdnBundle) continue;
      assembledByLibVer.set(`${baseLib}@${version}`, assembleFingerprint(baseLib, version, cdnBundle));
    }
  }
  console.log(
    `[index] precomputed ${assembledByLibVer.size} assembleFingerprints in ${((performance.now() - tAsm) / 1000).toFixed(1)}s`
  );
}
// [release] assembleFingerprint was the only reader of these, and it is never called again —
// detect() reads assembledByLibVer alone.
hashRangesByLib.clear();
expandedCache.clear();
cdnVariantHashesByLibVer.clear();
npmDepsData = null;  // assembleFingerprint copies nodes/edges out via .map(), so nothing points back

// ── per-site bench ──

interface DetectTimings { lookupMs: number; assembleMs: number; filterMs: number }

function detect(siteHashSet: Set<string>): {
  detected: number; scored: number; candLibs: number; timings: DetectTimings;
} {
  const t0 = performance.now();
  const matchedCdnLibVer = new Set<string>();
  const hitsByBaseLib = new Map<string, Set<string>>();
  for (const h of siteHashSet) {
    const hits = cdnHashToLibVers.get(h);
    if (!hits) continue;
    const baseLibsHit = new Set<string>();
    for (const { baseLib, version } of hits) {
      matchedCdnLibVer.add(`${baseLib}@${version}`);
      baseLibsHit.add(baseLib);
    }
    for (const bl of baseLibsHit) {
      let set = hitsByBaseLib.get(bl);
      if (!set) { set = new Set(); hitsByBaseLib.set(bl, set); }
      set.add(h);
    }
  }
  const candidateLibs = new Set<string>();
  for (const [bl, hset] of hitsByBaseLib) if (hset.size >= minCandidate) candidateLibs.add(bl);
  const t1 = performance.now();
  let scored = 0;
  let detected = 0;
  let assembleMs = 0;
  let filterMs = 0;
  for (const [baseLib, versions] of cdnVersionsByLib) {
    if (!candidateLibs.has(baseLib)) continue;
    for (const version of versions) {
      if (!matchedCdnLibVer.has(`${baseLib}@${version}`)) continue;
      const tA = performance.now();
      const cached = assembledByLibVer.get(`${baseLib}@${version}`)!;
      const { fileHashes, depgraph, mode } = cached;
      const tB = performance.now();
      assembleMs += tB - tA;
      if (mode === 'empty' || Object.keys(fileHashes).length === 0) continue;
      scored++;
      const tC = performance.now();
      const result = filterAndFindEntries(fileHashes, depgraph, { threshold: matchThreshold, siteHashSet });
      const tD = performance.now();
      filterMs += tD - tC;
      if (result.strictEntries.length > 0) detected++;
    }
  }
  return {
    detected, scored, candLibs: candidateLibs.size,
    timings: {
      lookupMs: t1 - t0,
      assembleMs,
      filterMs,
    },
  };
}

const siteFilter = process.env['SITE_FILTER'];
const allSites = fs.readdirSync(siteSrcDir)
  .filter((d) => fs.statSync(path.join(siteSrcDir, d)).isDirectory())
  .sort();
const targetSites = siteFilter
  ? siteFilter.split(',').map((s) => s.trim()).filter(Boolean)
  : allSites;

console.log(`[bench] running on ${targetSites.length} sites`);

interface BenchRow {
  site: string;
  files: number;
  failed: number;
  hashes: number;
  candLibs: number;
  scored: number;
  detected: number;
  // Hashing phases (per-site sums across all files)
  parseMs: number;
  scMs: number;
  collectorMs: number;
  pogMs: number;
  hashMs: number;
  hashTotalMs: number;
  // Detection phases
  lookupMs: number;
  assembleMs: number;
  filterMs: number;
  detectTotalMs: number;
  // End-to-end
  totalMs: number;
  // Peak process resources observed while this site was processed (MB).
  // worker_threads share the OS process, so main-thread rss covers the
  // extraction worker's isolate too.
  peakRssMB: number;
  peakHeapMB: number;
}

function r1(n: number): number { return Math.round(n * 10) / 10; }
function pad(n: number, w: number): string { return String(r1(n)).padStart(w); }

const rows: BenchRow[] = [];

// ── peak-memory sampling ──────────────────────────────────────────────────
// Q38: report resources for a single detection. RSS is process-wide (covers
// the extraction worker_thread, which shares this OS process). A 20 ms timer
// samples during the async extraction wait; detect() is synchronous, so we
// also read explicitly at each phase boundary to catch its transient peak.
const MB = 1024 * 1024;
let globalPeakRss = 0;
let globalPeakHeap = 0;
let windowPeakRss = 0;
let windowPeakHeap = 0;
function sampleMem(): void {
  const m = process.memoryUsage();
  const rss = m.rss / MB;
  const heap = m.heapUsed / MB;
  if (rss > globalPeakRss) globalPeakRss = rss;
  if (heap > globalPeakHeap) globalPeakHeap = heap;
  if (rss > windowPeakRss) windowPeakRss = rss;
  if (heap > windowPeakHeap) windowPeakHeap = heap;
}
// Resident footprint of the loaded index alone (one-off, shared across sites). Collect first
// when we can: index construction leaves the raw parsed JSON behind as garbage (see the
// `[release]` points above), and without a collection that garbage is counted as index.
if (exposedGlobal.gc) { exposedGlobal.gc(); exposedGlobal.gc(); }
const baselineRssMB = process.memoryUsage().rss / MB;
// What the resident baseline is actually made of. The on-disk cache is ~213 MB, so the
// ratio is worth being able to check rather than assume.
console.log(
  `[mem] retained after index build: ` +
  `assembledByLibVer=${assembledByLibVer.size} · cdnHashToLibVers=${cdnHashToLibVers.size} · ` +
  `fileLibById=${fileLibById.size} · cdnHashByLibVer=${cdnHashByLibVer.size} · ` +
  `embeddedFileLibVer=${embeddedFileLibVer.size} | heapUsed=${(process.memoryUsage().heapUsed / MB).toFixed(0)}MB ` +
  `rss=${baselineRssMB.toFixed(0)}MB`
);

async function runBench(): Promise<void> {
  // Background sampler; unref'd so it never keeps the process alive.
  const memTimer = setInterval(sampleMem, 20);
  memTimer.unref();
  for (let i = 0; i < targetSites.length; i++) {
    const site = targetSites[i];
    windowPeakRss = 0;
    windowPeakHeap = 0;
    const t0 = performance.now();
    sampleMem();
    await forceGc();
    // Each site runs in a fresh worker isolate — eliminates accumulated V8 IC
    // / heap state that otherwise made later sites' SC time blow up ~10×.
    const { hashes, fileCount, failCount, timings: ft } = await runExtractInWorker(site);
    const t1 = performance.now();
    await forceGc();
    sampleMem();
    const { detected, scored, candLibs, timings: dt } = detect(hashes);
    const t2 = performance.now();
    await forceGc();
    sampleMem(); // detect() is sync — captures its post-run resident peak
    const hashTotalMs = t1 - t0;
    const detectTotalMs = t2 - t1;
    rows.push({
      site, files: fileCount, failed: failCount, hashes: hashes.size,
      candLibs, scored, detected,
      parseMs: ft.parseMs, scMs: ft.scMs, collectorMs: ft.collectorMs,
      pogMs: ft.pogMs, hashMs: ft.hashMs, hashTotalMs,
      lookupMs: dt.lookupMs, assembleMs: dt.assembleMs, filterMs: dt.filterMs,
      detectTotalMs,
      totalMs: t2 - t0,
      peakRssMB: windowPeakRss,
      peakHeapMB: windowPeakHeap,
    });
    console.log(
      `[${(i + 1).toString().padStart(3)}/${targetSites.length}] ${site.padEnd(28)}` +
      ` files=${String(fileCount).padStart(4)} hashes=${String(hashes.size).padStart(6)}` +
      ` det=${String(detected).padStart(2)}/${String(scored).padStart(4)}` +
      ` | parse=${pad(ft.parseMs, 5)} sc=${pad(ft.scMs, 6)} coll=${pad(ft.collectorMs, 5)} pog=${pad(ft.pogMs, 6)} hash=${pad(ft.hashMs, 5)}` +
      ` | lookup=${pad(dt.lookupMs, 4)} assemble=${pad(dt.assembleMs, 5)} filter=${pad(dt.filterMs, 5)}` +
      ` | tot=${pad(t2 - t0, 7)}ms peakRss=${windowPeakRss.toFixed(0).padStart(5)}MB`
    );
  }
}

runBench().then(() => writeSummaryAndCsv()).catch((e) => {
  console.error('[bench] fatal:', e);
  process.exit(1);
});

function writeSummaryAndCsv(): void {

// ── summary ──

function pct(arr: number[], p: number): number {
  if (arr.length === 0) return 0;
  const s = [...arr].sort((a, b) => a - b);
  return s[Math.min(s.length - 1, Math.floor(s.length * p))];
}
function mean(arr: number[]): number {
  return arr.length === 0 ? 0 : arr.reduce((a, b) => a + b, 0) / arr.length;
}

function statRow(label: string, vals: number[]): void {
  const m = mean(vals);
  const p50 = pct(vals, 0.5);
  const p95 = pct(vals, 0.95);
  const mx = Math.max(...vals);
  console.log(
    `${label.padEnd(14)} mean=${m.toFixed(1).padStart(7)}ms` +
    `  p50=${p50.toFixed(1).padStart(7)}ms` +
    `  p95=${p95.toFixed(1).padStart(7)}ms` +
    `  max=${mx.toFixed(1).padStart(7)}ms`
  );
}

console.log('\n========== summary (per-site, ms) ==========');
console.log(`sites: ${rows.length}`);
console.log('--- hashing phases (sum over all JS files of a site) ---');
statRow('parse',     rows.map((r) => r.parseMs));
statRow('sc',        rows.map((r) => r.scMs));
statRow('collector', rows.map((r) => r.collectorMs));
statRow('pog',       rows.map((r) => r.pogMs));
statRow('hash',      rows.map((r) => r.hashMs));
statRow('hash TOTAL',rows.map((r) => r.hashTotalMs));
console.log('--- detection phases ---');
statRow('lookup',    rows.map((r) => r.lookupMs));
statRow('assemble',  rows.map((r) => r.assembleMs));
statRow('filter',    rows.map((r) => r.filterMs));
statRow('det TOTAL', rows.map((r) => r.detectTotalMs));
console.log('--- end-to-end ---');
statRow('TOTAL',     rows.map((r) => r.totalMs));
console.log('--- memory (peak resident set + heapUsed per site, MB) ---');
function memStatRow(label: string, vals: number[]): void {
  const m = mean(vals);
  const p50 = pct(vals, 0.5);
  const p95 = pct(vals, 0.95);
  const mx = Math.max(...vals);
  console.log(
    `${label.padEnd(14)} mean=${m.toFixed(0).padStart(6)}MB` +
    `  p50=${p50.toFixed(0).padStart(6)}MB` +
    `  p95=${p95.toFixed(0).padStart(6)}MB` +
    `  max=${mx.toFixed(0).padStart(6)}MB`
  );
}
memStatRow('peak RSS',  rows.map((r) => r.peakRssMB));
memStatRow('peak heap', rows.map((r) => r.peakHeapMB));
console.log(
  `index baseline RSS (loaded once, shared): ${baselineRssMB.toFixed(0)} MB` +
  `   |   global peak RSS: ${globalPeakRss.toFixed(0)} MB` +
  `   global peak heapUsed: ${globalPeakHeap.toFixed(0)} MB`
);

// ── CSV output ──

const header = [
  'site','files','failed','hashes','candLibs','scored','detected',
  'parseMs','scMs','collectorMs','pogMs','hashMs','hashTotalMs',
  'lookupMs','assembleMs','filterMs','detectTotalMs',
  'totalMs','peakRssMB','peakHeapMB',
].join(',');
const csvLines = [header];
for (const r of rows) {
  csvLines.push([
    r.site, r.files, r.failed, r.hashes, r.candLibs, r.scored, r.detected,
    r1(r.parseMs), r1(r.scMs), r1(r.collectorMs), r1(r.pogMs), r1(r.hashMs), r1(r.hashTotalMs),
    r1(r.lookupMs), r1(r.assembleMs), r1(r.filterMs), r1(r.detectTotalMs),
    r1(r.totalMs), r1(r.peakRssMB), r1(r.peakHeapMB),
  ].join(','));
}
const benchOutAbs = benchOut.startsWith('/') ? benchOut : path.join(rootDir, benchOut);
fs.mkdirSync(path.dirname(benchOutAbs), { recursive: true });
fs.writeFileSync(benchOutAbs, csvLines.join('\n') + '\n');
console.log(`\n[out] ${benchOutAbs}`);
}
